def _d3_transfer_full_narration():
    sections = []
    intros = {
        "BUY": (f"Now to the Gameweek {int(NEXT_GW)} transfer desk: who to buy, hold, and sell. "
                "This is driven by the numbers and projections, with the eye test as the final check. Starting with the buys."),
        "HOLD": "Now the holds.", "SELL": "Now the sells.",
    }
    for action in ("BUY", "HOLD", "SELL"):
        records = DAY3_TRANSFER_DESK.get(action, [])
        if len(records) != 5:
            raise RuntimeError(f"Transfer Desk requires five {action} cards")
        players = [{"i": int(record["index"]), "player_id": int(record["player_id"]),
                    "name": str(record["name"]),
                    "anchor": f"{vx_narration_player(int(record['player_id']))} from {vx_narration_team(int(record['team_id']))}"}
                   for record in records[:3]]
        text = "\n\n".join([intros[action]] + [_d3_desk_narr(action, index) for index in range(3)])
        intro_anchor = "Starting with the buys" if action == "BUY" else intros[action].rstrip(".")
        sections.append({"action": action, "intro": intro_anchor, "text": text,
                         "players": players,
                         "silent_cards": [{"i": int(record["index"]), "player_id": int(record["player_id"]),
                                           "name": str(record["name"])} for record in records[3:]],
                         "silent_card_seconds": 4.0})
    closing = "That is the desk. The key with transfers: don't react only to recent points. Compare the fixture, the projection, and the upside of the replacement. Now, let's review the Gameweek."
    globals()["TRANSFER_DESK_NARRATION_PLAN"] = {"version": "DESK_3_SPOKEN_2_SILENT_V1",
                                                "sections": sections, "closing": closing}
    return "\n\n".join([section["text"] for section in sections] + [closing])

