def validate_animation(key, info):
    if True:
        if key=="05_transfer_decision_desk":
            cues = info.get("sync_cues") or {}
            if cues.get("version") != "DESK_3_SPOKEN_2_SILENT_V1":
                raise RuntimeError("Transfer Desk animation needs the revised segmented audio; rerun Cell 18.")
            windows = list(cues.get("windows") or [])
            if len(windows) != 15 or [int(row["i"]) for row in windows] != list(range(15)):
                raise RuntimeError("Transfer Desk timeline must contain fifteen cards in selection order")
            if [bool(row["narrated"]) for row in windows] != [True, True, True, False, False] * 3:
                raise RuntimeError("Transfer Desk requires three narrated cards followed by two silent cards per action")
            if float(windows[0]["start"]) != 0.0:
                raise RuntimeError("Transfer Desk first card must be visible at frame zero")
            for index, window in enumerate(windows):
                if not float(window["start"]) <= float(window["exit_at"]) < float(window["settle"]):
                    raise RuntimeError("Transfer Desk card has invalid display timing")
                if index and abs(float(window["start"]) - float(windows[index-1]["settle"])) > .001:
                    raise RuntimeError("Transfer Desk card timeline has a gap or overlap")
            close_at = float(cues["closing_at"])
            zones = cues["zones"]
            globals().setdefault("_VX_TRANSFER_DESK_WINDOWS", {})[key] = windows
            globals().setdefault("_VX_TRANSFER_DESK_CLOSE", {})[key] = close_at
            globals().setdefault("_VX_TRANSFER_DESK_ZONE_TIMES", {})[key] = zones
            # The shell, BUY lane and first player card are visible from frame zero.
            return [
                {"sel": ".d3DeskZone.hold", "at": float(zones["hold"]), "dur": .35, "stagger": 0, "fx": "left"},
                {"sel": ".d3DeskZone.sell", "at": float(zones["sell"]), "dur": .35, "stagger": 0, "fx": "left"},
                {"sel": ".d3DeskClose", "at": close_at, "dur": .5, "stagger": 0, "fx": "zoom"},
            ]



def validate_payload(key, vx):
    if True:
        if key=="05_transfer_decision_desk":
            vx["transfer_desk_windows"]=globals().get(
                "_VX_TRANSFER_DESK_WINDOWS",{}
            ).get(key,[])
            vx["transfer_desk_closing_at"]=globals().get(
                "_VX_TRANSFER_DESK_CLOSE",{}
            ).get(key)
            vx["transfer_desk_zone_times"]=globals().get(
                "_VX_TRANSFER_DESK_ZONE_TIMES",{}
            ).get(key,{})
            if len(vx["transfer_desk_windows"]) != 15:
                raise RuntimeError(
                    f"Transfer Desk animation requires 15 card-flight windows; "
                    f"found {len(vx['transfer_desk_windows'])}"
                )
